// Weighted canary: 5% of requests go to v2; a hash of the user keeps users sticky.
function pickRandom(weightV2) {
  return Math.random() * 100 < weightV2 ? "v2" : "v1";
}
function pickSticky(userId, weightV2) {
  // same user id -> same bucket 0..99 every time (deterministic hash)
  const bucket = (userId * 2654435761 >>> 0) % 100;
  return bucket < weightV2 ? "v2" : "v1";
}
const N = 10000;
let v2 = 0;
for (let i = 0; i < N; i++) if (pickRandom(5) === "v2") v2++;
console.log("random split of", N, "requests: v2 share is about 5%, got", v2 > 350 && v2 < 650 ? "~5%" : "off");

let stickyV2 = 0;
for (let u = 1; u <= N; u++) if (pickSticky(u, 5) === "v2") stickyV2++;
console.log("sticky split of", N, "users: v2 users =", stickyV2);

const user = 1234;
const seen = [];
for (let k = 0; k < 5; k++) seen.push(pickSticky(user, 5));
console.log("user", user, "five requests ->", seen.join(","));
// raise the weight to 25: users in buckets 0-4 stay on v2, more join
console.log("user 1234 at 25%:", pickSticky(user, 25), " bucket =", (user * 2654435761 >>> 0) % 100);
